// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the caller 'from' and a uint value v and the length of recipients
    // we pass a recording/reverting helper as the callee so we can control whether it reverts
    function testFuzz_property(address from, uint256 v, uint32 tosLen, bool shouldRevert) public {
        // keep tosLen reasonably bounded but allow >0 since require(_tos.length>0)
        uint256 len = bound(tosLen, 1, 10);

        // build an array of distinct addresses as _tos; fuzzing 'from' and 'v' remains
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // derive addresses from the faker 'from' to keep them concrete but varied
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // deploy helper that can either revert or accept and record calls
        RevertingRecorder helper = new RevertingRecorder(shouldRevert);

        // call transfer and observe whether it reverts using try/catch
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): If the callee would revert on the called selector,
        // then c.transfer must also revert (ok == false). The reference implementation makes the external
        // calls inside the loop and requires their success, so when helper is set to revert these calls
        // the overall transfer must revert. The mutant that removed the calls will leave ok == true
        // when shouldRevert == true, so this assertion distinguishes them.
        assertTrue(shouldRevert ? !ok : ok);
    }
}

// Helper that records calls and optionally reverts. It implements the exact signature
// transferFrom(address,address,uint256) so that ABI decoding happens and it can revert deterministically.
contract RevertingRecorder {
    bool public shouldRevert;
    // simple counters / records in case needed for inspection
    uint public callCount;
    event Called(address from, address to, uint256 v);

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        callCount += 1;
        emit Called(from, to, value);
        if (shouldRevert) {
            revert("revert on purpose");
        }
        return true;
    }
}
